INSERT INTO profiles (id, user, username, display_name, bio, city, rating_avg, rating_count, sales, response_minutes, verified, joined_at) VALUES

  (1, (SELECT id FROM _user WHERE username = 'admin'), 'admin', 'Tengasell Official', 'Platform operations account. Trust & safety, dispute resolution and verified seller programmes.', 'Harare', 5, 0, 0, 15, 1, '2025-08-25T01:19:38Z'),
  (2, (SELECT id FROM _user WHERE username = 'takudzwa'), 'takudzwa', 'Takudzwa Mutasa', 'Gadgets and tools. 9 years selling on Tengasell. Based in Avondale, Harare. Pickup welcome.', 'Harare', 4.9, 412, 611, 22, 1, '2025-10-04T01:19:38Z'),
  (3, (SELECT id FROM _user WHERE username = 'nyasha'), 'nyasha', 'Nyasha Katuruza', 'Phones in Bulawayo. Every device bench-tested for 48 hours before listing. Swap negotiable.', 'Bulawayo', 4.8, 289, 344, 35, 1, '2025-11-03T01:19:38Z'),
  (4, (SELECT id FROM _user WHERE username = 'rufaro'), 'rufaro', 'Rufaro Chikafu — Solar Queen', 'Off-grid power solutions. Complete kits installed anywhere in Zimbabwe. COC certificate included on installs.', 'Harare', 4.9, 517, 720, 12, 1, '2025-09-14T01:19:38Z'),
  (5, (SELECT id FROM _user WHERE username = 'blessing'), 'blessing', 'Blessing Shoko', 'Authentic fashion imports. 100% genuine or triple your money back.', 'Mutare', 4.7, 178, 253, 55, 0, '2026-02-01T01:19:38Z'),
  (6, (SELECT id FROM _user WHERE username = 'kudzai'), 'kudzai', 'Kudzai Marange', 'Vehicles and spares. Viewings by appointment in Gweru. AA inspection welcome on any unit.', 'Gweru', 4.8, 96, 118, 90, 1, '2025-12-23T01:19:38Z'),
  (7, (SELECT id FROM _user WHERE username = 'tatenda'), 'tatenda', 'Tatenda Nyoni', 'Collectibles, coins and banknotes. Lifetime collector turned dealer. COA on rarities.', 'Harare', 5, 143, 187, 18, 1, '2026-02-21T01:19:38Z'),
  (8, (SELECT id FROM _user WHERE username = 'tendai'), 'tendai', 'Tendai Chirwa', 'Refurbished business laptops. Corporate lease returns with new SSDs and fresh Windows.', 'Harare', 4.8, 234, 299, 26, 1, '2025-12-03T01:19:38Z'),
  (9, (SELECT id FROM _user WHERE username = 'chipo'), 'chipo', 'Chipo Moyo', 'Home appliances with warranty. Family-run since 2019. Bulawayo pickup or nationwide courier.', 'Bulawayo', 4.7, 155, 201, 40, 1, '2026-01-12T01:19:38Z'),
  (10, (SELECT id FROM _user WHERE username = 'farai'), 'farai', 'Farai Dube', 'Farm inputs and machinery. Bulk deals for cooperatives. Masvingo based, deliver countrywide.', 'Masvingo', 4.8, 88, 121, 70, 0, '2026-04-12T01:19:38Z'),
  (11, (SELECT id FROM _user WHERE username = 'simba'), 'simba', 'Simba Gora', 'Buyer and collector. Gaming gear and music equipment. Harare.', 'Harare', 4.9, 57, 61, 30, 0, '2026-05-22T01:19:38Z'),
  (12, (SELECT id FROM _user WHERE username = 'anesu'), 'anesu', 'Anesu Tichafa', 'African art and sculpture dealer. Vic Falls gallery. Shipping crated and insured.', 'Victoria Falls', 4.9, 74, 98, 45, 1, '2026-03-23T01:19:38Z'),
  (13, (SELECT id FROM _user WHERE username = 'mukudzei'), 'mukudzei', 'Mukudzei Hove', 'Photography gear. Bodies, glass and lighting. Trades welcome.', 'Harare', 4.7, 61, 73, 38, 0, '2026-05-02T01:19:38Z'),
  (14, (SELECT id FROM _user WHERE username = 'shamiso'), 'shamiso', 'Shamiso Banda', 'Books, media and backpacks. Bibliophile shipping nationwide.', 'Harare', 4.8, 44, 52, 60, 0, '2026-06-21T01:19:38Z'),
  (15, (SELECT id FROM _user WHERE username = 'panashe'), 'panashe', 'Panashe Zvobgo', 'Enthusiast buyer. Solar tinkerer.', 'Harare', 4.6, 12, 14, 120, 0, '2026-08-20T01:19:38Z'),
