INSERT INTO auctions (id, user, seller_username, title, slug, description, category, condition, start_price, current_price, buy_now_price, reserve_price, bid_count, watch_count, views, shipping_fee, shipping, city, ends_at, started_at, status, extension_count, featured, images, created_at, updated_at) VALUES

  (1001, (SELECT id FROM _user WHERE username = 'nyasha'), 'nyasha', 'Apple iPhone 13 128GB Midnight — Unlocked, Battery 89%', 'apple-iphone-13-128gb-midnight-unlocked-battery-89', 'Genuine iPhone 13 in Midnight. 89% battery health, unlocked for all networks. Screen has had a tempered protector since day one — no scratches underneath. Includes box, cable and a genuine Apple silicone case. Face ID perfect, True Tone intact. Bench-tested 48 hours: all cameras, mics, speakers and 5G verified.', 'phones', 'used', 180, 251, 420, NULL, 12, 46, 1840, 5, 'courier', 'Bulawayo', '2026-10-19T01:53:38Z', '2026-10-14T01:24:38Z', 'live', 0, 1, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/b2e4088d6f77.jpg","https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/a23823246d9f.jpg"]', '2026-10-14T01:24:38Z', '2026-10-14T02:24:38Z'),
  (1002, (SELECT id FROM _user WHERE username = 'nyasha'), 'nyasha', 'Samsung Galaxy S23 256GB Phantom Black — Dual SIM', 'samsung-galaxy-s23-256gb-phantom-black-dual-sim', 'Galaxy S23 Snapdragon variant. 256GB storage, 8GB RAM. Battery health excellent (92%). Comes with original box, 25W charger and two unused screen protectors. Snapped one pic of the screen showing settings for sceptics. Network tested on Econet, NetOne and TelOne.', 'phones', 'used', 250, 445, 650, NULL, 15, 61, 2210, 5, 'courier', 'Bulawayo', '2026-10-19T04:29:38Z', '2026-10-15T01:24:38Z', 'live', 0, 0, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/5d5db6b99a9b.jpg","https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/22945ea3954b.jpg"]', '2026-10-15T01:24:38Z', '2026-10-15T02:24:38Z'),
  (1003, (SELECT id FROM _user WHERE username = 'takudzwa'), 'takudzwa', 'iPhone 14 Pro Max 256GB Deep Purple — 275 Cycles', 'iphone-14-pro-max-256gb-deep-purple-275-cycles', 'Flagship with Dynamic Island and Always-On display. 256GB, battery at 275 cycles (86% health). Unlocked. Includes box and braided USB-C cable. Small scuff on titanium frame (photo 2) — screen flawless. Trade-in of your old iPhone considered, mention in Q&A.', 'phones', 'used', 300, 720, NULL, NULL, 21, 98, 3350, 8, 'courier', 'Harare', '2026-10-19T08:09:38Z', '2026-10-13T01:24:38Z', 'live', 0, 1, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/b2e4088d6f77.jpg","https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/a23823246d9f.jpg"]', '2026-10-13T01:24:38Z', '2026-10-13T02:24:38Z'),
  (1004, (SELECT id FROM _user WHERE username = 'nyasha'), 'nyasha', 'Tecno Camon 30 Pro 5G 512GB — 3 Months Old', 'tecno-camon-30-pro-5g-512gb-3-months-old', 'Barely 3 months old, 512GB storage, 70W charging. Complete box, screen guard applied, TPU case included. Reason for sale: upgraded to iPhone for iMessage work reasons. Receipt available from official Tecno store.', 'phones', 'like-new', 90, 145, 210, NULL, 6, 18, 640, 4, 'courier', 'Bulawayo', '2026-10-20T01:29:38Z', '2026-10-17T01:24:38Z', 'live', 0, 0, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/5d5db6b99a9b.jpg","https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/22945ea3954b.jpg"]', '2026-10-17T01:24:38Z', '2026-10-17T02:24:38Z'),
  (1005, (SELECT id FROM _user WHERE username = 'takudzwa'), 'takudzwa', 'iPhone 11 64GB — Fair, Battery 74%', 'iphone-11-64gb-fair-battery-74', 'Honest listing: battery at 74% (will need service eventually), light scratches on back glass, screen clean with minor micro-scratches visible at angle. Everything works — Face ID, both cameras, WiFi, all buttons. Sold as-is, priced accordingly. Great first iPhone.', 'phones', 'fair', 80, 122, NULL, NULL, 7, 22, 810, 5, 'courier', 'Harare', '2026-10-19T02:54:38Z', '2026-10-16T01:24:38Z', 'live', 0, 0, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/b2e4088d6f77.jpg","https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/a23823246d9f.jpg"]', '2026-10-16T01:24:38Z', '2026-10-16T02:24:38Z'),
  (1006, (SELECT id FROM _user WHERE username = 'nyasha'), 'nyasha', 'Samsung Galaxy A15 128GB Brand Sealed', 'samsung-galaxy-a15-128gb-brand-sealed', 'Factory sealed, never opened. 6.5" AMOLED, 5000mAh, 25W charging. Perfect backup or gift phone. One-year warranty from Samsung Zimbabwe. Buy-now includes a free clear case.', 'phones', 'new', 45, 68, 99, NULL, 4, 11, 425, 4, 'courier', 'Bulawayo', '2026-10-21T01:19:38Z', '2026-10-18T01:24:38Z', 'live', 0, 0, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/5d5db6b99a9b.jpg","https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/22945ea3954b.jpg"]', '2026-10-18T01:24:38Z', '2026-10-18T02:24:38Z'),
  (1007, (SELECT id FROM _user WHERE username = 'takudzwa'), 'takudzwa', 'PlayStation 5 Slim Disc + 2 DualSense + FC25', 'playstation-5-slim-disc-2-dualsense-fc25', 'PS5 Slim disc edition, 1TB, bought December. Includes FC25 disc, Astro''s Playroom, and TWO DualSense controllers (one barely used). Runs whisper quiet, HDMI 2.1 cable included. Receipt and remaining warranty transfer to buyer. Harare pickup in Avondale welcome.', 'electronics', 'used', 200, 344, 480, NULL, 11, 84, 2960, 10, 'courier', 'Harare', '2026-10-19T02:14:38Z', '2026-10-15T01:24:38Z', 'live', 0, 1, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/4feaca289391.jpg","https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/4c005c3c9e3f.jpg"]', '2026-10-15T01:24:38Z', '2026-10-15T02:24:38Z'),
  (1008, (SELECT id FROM _user WHERE username = 'simba'), 'simba', 'Nintendo Switch OLED Zelda Edition + 4 Games', 'nintendo-switch-oled-zelda-edition-4-games', 'Limited edition Zelda OLED Switch. Joy-cons drift-free (tested). Included: Zelda TOTK, Mario Kart 8, Smash Ultimate, Metroid Dread (cartridges). Screen protector on since new, includes dock, grip and carrying case.', 'electronics', 'used', 150, 232, NULL, NULL, 9, 38, 1490, 8, 'courier', 'Harare', '2026-10-19T04:59:38Z', '2026-10-14T01:24:38Z', 'live', 0, 0, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/4852513cf85d.jpg"]', '2026-10-14T01:24:38Z', '2026-10-14T02:24:38Z'),
  (1009, (SELECT id FROM _user WHERE username = 'takudzwa'), 'takudzwa', 'JBL PartyBox 310 — 240W Bluetooth Party Speaker', 'jbl-partybox-310-240w-bluetooth-party-speaker', 'The one that wakes the neighbours. 240W, light show, 18-hour battery. Used for one wedding season, fully functional. Comes with original cover and charging cable. PartyBoost pairable.', 'electronics', 'used', 120, 195, NULL, NULL, 8, 27, 980, 12, 'courier', 'Harare', '2026-10-19T06:49:38Z', '2026-10-16T01:24:38Z', 'live', 0, 0, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/ef78e21efb29.jpg"]', '2026-10-16T01:24:38Z', '2026-10-16T02:24:38Z'),
  (1010, (SELECT id FROM _user WHERE username = 'nyasha'), 'nyasha', 'Soundcore Liberty 4 NC Earbuds — Active Noise Cancelling', 'soundcore-liberty-4-nc-earbuds-active-noise-cancelling', 'LDAC hi-res audio, adaptive ANC, wireless charging case. Complete with all ear tips and original box. Only selling because I got gifted the Pro version.', 'electronics', 'like-new', 20, 34, NULL, NULL, 5, 9, 415, 3, 'courier', 'Bulawayo', '2026-10-19T02:44:38Z', '2026-10-17T01:24:38Z', 'live', 0, 0, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/9bc73df91ded.jpeg","https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/4014a391c81a.jpg"]', '2026-10-17T01:24:38Z', '2026-10-17T02:24:38Z'),
  (1011, (SELECT id FROM _user WHERE username = 'mukudzei'), 'mukudzei', 'Canon EOS 90D + 18-135mm USM — 14k Shutter Count', 'canon-eos-90d-18-135mm-usm-14k-shutter-count', 'Workhorse 32.5MP APS-C DSLR. Shutter count 14,270 (rated 150k). Includes EF-S 18-135mm f/3.5-5.6 IS USM, two genuine Canon batteries, 64GB SanDisk Extreme, and a Lowepro shoulder bag. Sensor cleaned last month. Sharp photos in listing taken with this exact body.', 'electronics', 'used', 400, 745, 950, NULL, 12, 52, 2140, 15, 'courier', 'Harare', '2026-10-19T15:19:38Z', '2026-10-13T01:24:38Z', 'live', 0, 1, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/73b2dc6446e2.png","https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/15cb3fb95b68.jpg"]', '2026-10-13T01:24:38Z', '2026-10-13T02:24:38Z'),
  (1012, (SELECT id FROM _user WHERE username = 'mukudzei'), 'mukudzei', 'Nikon FM2 35mm Film Camera + 50mm f/1.8 — Collector Grade', 'nikon-fm2-35mm-film-camera-50mm-f-1-8-collector-grade', 'The legendary FM2 — titanium shutter, works without batteries at all speeds. Cosmetics 9/10, meter accurate, film advance smooth. Nikkor 50mm f/1.8 AI lens is clear, no fungus, no oil on blades. A joy for film shooters and collectors alike.', 'electronics', 'used', 150, 264, NULL, NULL, 9, 31, 1130, 10, 'courier', 'Harare', '2026-10-20T08:44:38Z', '2026-10-14T01:24:38Z', 'live', 0, 0, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/64c9a69617ba.png"]', '2026-10-14T01:24:38Z', '2026-10-14T02:24:38Z'),
  (1013, (SELECT id FROM _user WHERE username = 'chipo'), 'chipo', 'Samsung 55" Crystal UHD 4K Smart TV (2023)', 'samsung-55-crystal-uhd-4k-smart-tv-2023', '55-inch Crystal UHD with Tizen smart hub. Netflix, YouTube and Showmax all logged in smoothly on our fibre. Wall-mountable (bracket included at buy-now). No dead pixels, no backlight bleed. Original remote and box.', 'electronics', 'used', 250, 388, 520, NULL, 10, 44, 1720, 20, 'courier', 'Bulawayo', '2026-10-19T05:39:38Z', '2026-10-15T01:24:38Z', 'live', 0, 0, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/bb7301d3e880.jpg"]', '2026-10-15T01:24:38Z', '2026-10-15T02:24:38Z'),
  (1014, (SELECT id FROM _user WHERE username = 'simba'), 'simba', 'Numark Party Mix II DJ Controller + Stand', 'numark-party-mix-ii-dj-controller-stand', 'Two-channel DJ controller with built-in light show and speakers monitor. Serato DJ Lite included. Crossfader smooth, jog wheels responsive. Perfect starter rig — I upgraded to FLX6. Includes laptop stand.', 'electronics', 'used', 90, 152, NULL, NULL, 6, 14, 530, 10, 'courier', 'Harare', '2026-10-20T10:39:38Z', '2026-10-16T01:24:38Z', 'live', 0, 0, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/3ba54bc40fcb.jpeg"]', '2026-10-16T01:24:38Z', '2026-10-16T02:24:38Z'),
  (1015, (SELECT id FROM _user WHERE username = 'tendai'), 'tendai', 'MacBook Air M2 8GB/256GB Midnight — 38 Cycles', 'macbook-air-m2-8gb-256gb-midnight-38-cycles', 'MacBook Air M2, 8GB unified memory, 256GB SSD. Battery: 38 cycles, 96% health. Midnight colour shows usual micro-marks but no dents. macOS Sequoia, includes original 30W charger and box. Perfect student or office machine — handles Xcode and Lightroom happily.', 'computers', 'used', 350, 690, 950, NULL, 14, 112, 3820, 10, 'courier', 'Harare', '2026-10-19T03:19:38Z', '2026-10-14T01:24:38Z', 'live', 0, 1, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/a6bd6ec12c3b.jpg","https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/8b4d1e08aa5a.jpg"]', '2026-10-14T01:24:38Z', '2026-10-14T02:24:38Z'),
  (1016, (SELECT id FROM _user WHERE username = 'tendai'), 'tendai', 'Dell Latitude 7420 i7-1185G7 16GB/512GB FHD', 'dell-latitude-7420-i7-1185g7-16gb-512gb-fhd', 'Corporate lease return, professionally refurbished: brand new 512GB NVMe SSD, fresh Windows 11 Pro, new thermal paste, sanitized keyboard. i7 11th gen, 16GB RAM, fingerprint reader, backlit keyboard. 90-day warranty from us.', 'computers', 'refurbished', 180, 320, NULL, NULL, 9, 33, 1240, 8, 'courier', 'Harare', '2026-10-19T04:14:38Z', '2026-10-16T01:24:38Z', 'live', 0, 0, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/adbecd5c9af9.jpg","https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/6ae242fbf2d9.jpg"]', '2026-10-16T01:24:38Z', '2026-10-16T02:24:38Z'),
  (1017, (SELECT id FROM _user WHERE username = 'tendai'), 'tendai', 'HP EliteBook 840 G7 i5 16GB — Business Grade', 'hp-elitebook-840-g7-i5-16gb-business-grade', 'EliteBook 840 G7, i5-10310U, 16GB, new 256GB NVMe. Magnesium-alloy body, spill-resistant keyboard. Windows 11 Pro activated. Ideal office laptop with webcam privacy shutter. Our refurb includes full diagnostic report in box.', 'computers', 'refurbished', 150, 254, NULL, NULL, 7, 21, 890, 8, 'courier', 'Harare', '2026-10-19T08:19:38Z', '2026-10-17T01:24:38Z', 'live', 0, 0, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/adbecd5c9af9.jpg","https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/6ae242fbf2d9.jpg"]', '2026-10-17T01:24:38Z', '2026-10-17T02:24:38Z'),
  (1018, (SELECT id FROM _user WHERE username = 'tendai'), 'tendai', 'Lenovo ThinkPad T14 Gen2 Ryzen 7 16GB', 'lenovo-thinkpad-t14-gen2-ryzen-7-16gb', 'ThinkPad T14 Gen 2, Ryzen 7 Pro 5850U (8 cores), 16GB RAM, new 512GB SSD. The keyboard everyone raves about. Linux-friendly — happy to pre-install Ubuntu if the winner prefers.', 'computers', 'refurbished', 130, 198, NULL, NULL, 5, 15, 640, 8, 'courier', 'Harare', '2026-10-20T02:19:38Z', '2026-10-17T01:24:38Z', 'live', 0, 0, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/adbecd5c9af9.jpg","https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/6ae242fbf2d9.jpg"]', '2026-10-17T01:24:38Z', '2026-10-17T02:24:38Z'),
  (1019, (SELECT id FROM _user WHERE username = 'mukudzei'), 'mukudzei', 'Custom Gaming PC — RTX 3060 / Ryzen 5 5600 / 16GB', 'custom-gaming-pc-rtx-3060-ryzen-5-5600-16gb', 'Hand-built gaming rig: RTX 3060 12GB, Ryzen 5 5600, 16GB DDR4 3600, 1TB NVMe + 2TB HDD, 600W Bronze. Runs Cyberpunk 2077 at 1080p ultra 75fps. Tempered glass case with 6 ARGB fans. Cables managed properly (photo 2). Stressed tested 6 hours Prime95 + FurMark — rock stable.', 'computers', 'used', 400, 722, NULL, NULL, 11, 47, 1980, 25, 'courier', 'Harare', '2026-10-19T13:19:38Z', '2026-10-13T01:24:38Z', 'live', 0, 0, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/a6bd6ec12c3b.jpg","https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/8b4d1e08aa5a.jpg"]', '2026-10-13T01:24:38Z', '2026-10-13T02:24:38Z'),
  (1020, (SELECT id FROM _user WHERE username = 'rufaro'), 'rufaro', '5kVA Hybrid Inverter + 2× 100Ah LiFePO4 — Complete Kit', '5kva-hybrid-inverter-2-100ah-lifepo4-complete-kit', 'Brand new, sealed: 5kVA 48V hybrid inverter (parallel-ready, WiFi monitoring), 2× 100Ah 51.2V LiFePO4 batteries (6000 cycles, 10-year design life), and disconnects. Prewired kit — your electrician connects in under 2 hours. Load-shedding proof: runs fridge, TV, lights, WiFi and a borehole pump simultaneously. Installation available countrywide (quoted separately). COC certificate included on installs we do.', 'solar-power', 'new', 600, 980, 1450, NULL, 13, 128, 4120, 40, 'national', 'Harare', '2026-10-19T02:24:38Z', '2026-10-14T01:24:38Z', 'live', 0, 1, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/9ee284b0050d.jpeg","https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/6898631193ca.png"]', '2026-10-14T01:24:38Z', '2026-10-14T02:24:38Z'),
  (1021, (SELECT id FROM _user WHERE username = 'rufaro'), 'rufaro', '550W Monocrystalline Solar Panels — Bundle of 4', '550w-monocrystalline-solar-panels-bundle-of-4', 'Four × 550W A-grade mono panels, 25-year performance warranty, IP68 junction box. That''s 2.2kW of harvesting power. Rails and clamps available at extra cost. Delivery countrywide via our courier partners or collect from Msasa.', 'solar-power', 'new', 200, 371, NULL, NULL, 9, 73, 2640, 30, 'national', 'Harare', '2026-10-19T06:19:38Z', '2026-10-15T01:24:38Z', 'live', 0, 0, '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/41983cdaa1c4.jpg","https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/955f1743d01d.jpg"]', '2026-10-15T01:24:38Z', '2026-10-15T02:24:38Z'),
