INSERT INTO questions (id, auction_id, user, asker_username, body, answer, answered_at, created_at) VALUES

  (1, 1001, (SELECT id FROM _user WHERE username = 'panashe'), 'panashe', 'Does it come with the original box? And is the battery still above 85%?', 'Yes, box included and battery health is 89% — screenshot of settings in photo 4. Thanks!', '2026-10-18T21:59:38Z', '2026-10-18T20:59:38Z'),
  (2, 1020, (SELECT id FROM _user WHERE username = 'ruvarashe'), 'ruvarashe', 'Do you install in Bulawayo? And can this run a fridge through the night?', 'We install countrywide — Bulawayo included (call-out quoted at cost). Yes: fridge + TV + lights + WiFi comfortably overnight on this kit. Add a second battery if you also want the borehole pump.', '2026-10-18T23:49:38Z', '2026-10-18T23:19:38Z'),
  (3, 1026, (SELECT id FROM _user WHERE username = 'mukudzei'), 'mukudzei', 'Hi — is the kit still under the hardware warranty? And why 8 months only?', 'Dish warranty is 12 months from activation (so 4 months left, transfers with the account). Selling because I travel more now and moved to the Mini.', '2026-10-19T00:34:38Z', '2026-10-19T00:09:38Z'),
  (4, 1035, (SELECT id FROM _user WHERE username = 'panashe'), 'panashe', 'Any accident history? Can I send my mechanic to inspect in Gweru?', 'Zero accidents — books and history complete. Your mechanic is very welcome, inspections by appointment, call the number on my profile. Happy bidding!', '2026-10-18T16:59:38Z', '2026-10-18T15:19:38Z'),
  (5, 1031, (SELECT id FROM _user WHERE username = 'chipo'), 'chipo', 'Can you do a live video call to verify authenticity before the auction ends?', 'Absolutely — message me to arrange, happy to do a Legit-Check call with the shoes on camera.', '2026-10-19T00:49:38Z', '2026-10-19T00:24:38Z'),
  (6, 1015, (SELECT id FROM _user WHERE username = 'ruvarashe'), 'ruvarashe', 'Any dents or bent corners? Does it come with the charger?', 'No dents, corners straight (macro photos available on request). Original 30W charger and box included.', '2026-10-18T22:49:38Z', '2026-10-18T22:09:38Z'),
  (7, 1007, (SELECT id FROM _user WHERE username = 'shamiso'), 'shamiso', 'Can I pick up in Avondale this weekend if I win?', 'Yes — pickup available Saturday morning, cash or pre-paid. Winning bid can also courier if you prefer.', '2026-10-19T00:19:38Z', '2026-10-18T23:59:38Z'),
  (8, 1041, (SELECT id FROM _user WHERE username = 'simba'), 'simba', 'Is the serial number the AA prefix series? Great frame by the way.', NULL, NULL, '2026-10-19T00:59:38Z'),
  (9, 1033, (SELECT id FROM _user WHERE username = 'anesu'), 'anesu', 'How is the accuracy? Do you timegraph it?', NULL, NULL, '2026-10-18T23:49:38Z'),
  (10, 1045, (SELECT id FROM _user WHERE username = 'blessing'), 'blessing', 'Does it handle fertiliser placement as well or seed only?', NULL, NULL, '2026-10-19T00:39:38Z');

