INSERT INTO messages (id, thread_id, user, sender_username, body, created_at) VALUES

  (1, 1, (SELECT id FROM _user WHERE username = 'panashe'), 'panashe', 'Hi Rufaro, I''m keen on the 5kVA kit. What would installation in Bulawayo cost on top?', '2026-10-18T20:19:38Z'),
  (2, 1, (SELECT id FROM _user WHERE username = 'rufaro'), 'rufaro', 'Hi Panashe! Install in Byo is $120 including railings for a wall mount. Takes our team about 3 hours.', '2026-10-18T20:39:38Z'),
  (3, 1, (SELECT id FROM _user WHERE username = 'panashe'), 'panashe', 'Perfect. And COC certificate?', '2026-10-18T20:44:38Z'),
  (4, 1, (SELECT id FROM _user WHERE username = 'rufaro'), 'rufaro', 'Included on all installs we do — insurance-ready. If you win, we book a date within 48h of payment.', '2026-10-18T20:59:38Z'),
  (5, 1, (SELECT id FROM _user WHERE username = 'panashe'), 'panashe', 'Great, I''ll bid tonight 🔆', '2026-10-18T21:09:38Z'),
  (6, 2, (SELECT id FROM _user WHERE username = 'mukudzei'), 'mukudzei', 'Hello — winning this. How does the account transfer work exactly?', '2026-10-18T23:49:38Z'),
  (7, 2, (SELECT id FROM _user WHERE username = 'rufaro'), 'rufaro', 'Congrats! It''s a kit transfer on the Starlink app — I enter your email, you accept, takes 5 minutes. We can do it at handover in Borrowdale.', '2026-10-18T23:59:38Z'),
  (8, 2, (SELECT id FROM _user WHERE username = 'mukudzei'), 'mukudzei', 'Brilliant. I''ll complete payment now — the 48h SLA is tight!', '2026-10-19T00:09:38Z'),
  (9, 3, (SELECT id FROM _user WHERE username = 'ruvarashe'), 'ruvarashe', 'Hi, could you send close-up photos of the corners and the battery cycle count screen?', '2026-10-18T21:59:38Z'),
  (10, 3, (SELECT id FROM _user WHERE username = 'tendai'), 'tendai', 'Sure — just posted them to the listing (photos 5-8). Cycle count is 38, 96% health.', '2026-10-18T22:09:38Z'),
  (11, 3, (SELECT id FROM _user WHERE username = 'ruvarashe'), 'ruvarashe', 'Thank you, looks clean. Watching this one 👀', '2026-10-18T22:14:38Z'),
  (12, 4, (SELECT id FROM _user WHERE username = 'tatenda'), 'tatenda', 'Do you accept part payment then balance? I can do $15k now.', '2026-10-18T18:39:38Z'),
  (13, 4, (SELECT id FROM _user WHERE username = 'kudzai'), 'kudzai', 'Sorry, auction rules apply — full settlement within 48h of winning per Tengasell SLA. No part payments, protects both sides.', '2026-10-18T18:59:38Z'),
  (14, 4, (SELECT id FROM _user WHERE username = 'tatenda'), 'tatenda', 'Understood, fair enough. My bank pre-approval is in process.', '2026-10-18T19:09:38Z');

