  (1, 1, (SELECT id FROM _user WHERE username = 'simba'), (SELECT id FROM _user WHERE username = 'rufaro'), 'rufaro', 'as_buyer', 5, 'Rufaro is world-class. Delivered and installed next morning, COC included. Power stayed on through 12 hours of shedding — life-changing!', '2026-10-17T17:59:38Z'),
  (2, 1, (SELECT id FROM _user WHERE username = 'rufaro'), (SELECT id FROM _user WHERE username = 'simba'), 'simba', 'as_seller', 5, 'Instant payment, smooth handover, pleasure to deal with.', '2026-10-17T18:19:38Z'),
  (3, 2, (SELECT id FROM _user WHERE username = 'ruvarashe'), (SELECT id FROM _user WHERE username = 'tendai'), 'tendai', 'as_buyer', 4, 'Item exactly as described, packed beautifully. Courier took an extra day (not seller''s fault). Would buy again.', '2026-10-18T12:19:38Z'),
  (4, 2, (SELECT id FROM _user WHERE username = 'tendai'), (SELECT id FROM _user WHERE username = 'ruvarashe'), 'ruvarashe', 'as_seller', 5, 'Paid within the hour. Recommended buyer.', '2026-10-18T12:29:38Z');

